const $ = (s, root = document) => root.querySelector(s);
const $$ = (s, root = document) => [...root.querySelectorAll(s)];
const escape = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons = {
 search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m15.5 15.5 4.5 4.5"/>', heart:'<path d="M20.5 9c0 4.5-8.5 10-8.5 10S3.5 13.5 3.5 9a4.5 4.5 0 0 1 8.5-2 4.5 4.5 0 0 1 8.5 2Z"/>', calendar:'<rect x="3.5" y="5.5" width="17" height="15" rx="2"/><path d="M7.5 3v5M16.5 3v5M3.5 11h17M8 15h2M14 15h2"/>', message:'<path d="M20.5 11.5a8.5 8 0 0 1-8.5 8 10 10 0 0 1-3.5-.6L4 21l1.5-4.3a7.6 7.6 0 0 1-2-5.2 8.5 8 0 0 1 17 0Z"/><path d="M8 10h8M8 14h5"/>', profile:'<circle cx="12" cy="8" r="3.5"/><path d="M4.5 21v-2a7.5 7.5 0 0 1 15 0v2"/>', space:'<path d="m3.5 10 8.5-6 8.5 6v10h-17Z"/><path d="M8 20v-8h8v8M8 15h8"/>', help:'<circle cx="12" cy="12" r="9"/><path d="M9.5 9a2.5 2.5 0 1 1 4 2c-1 .6-1.5 1.2-1.5 2.5M12 17h.01"/>', chevron:'<path d="m9 5 7 7-7 7"/>', plus:'<path d="M12 4v16M4 12h16"/>', close:'<path d="m6 6 12 12M18 6 6 18"/>', pin:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0Z"/><circle cx="12" cy="10" r="2.5"/>', arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>', back:'<path d="M20 12H4m6-6-6 6 6 6"/>', filters:'<path d="M4 7h16M4 17h16"/><circle cx="8" cy="7" r="2" fill="currentColor"/><circle cx="16" cy="17" r="2" fill="currentColor"/>', map:'<path d="m3 6 6-3 6 3 6-3v15l-6 3-6-3-6 3ZM9 3v15M15 6v15"/>', parking:'<rect x="4" y="3" width="16" height="18" rx="3"/><path d="M9 17V7h4a3 3 0 0 1 0 6H9"/>', box:'<path d="m3 7 9-4 9 4-9 4ZM3 7v10l9 4 9-4V7M12 11v10M7 5l10 4"/>', workshop:'<path d="m14 4 2 2-3 5 5 5a2 2 0 0 1-3 3l-5-5-5 3-2-2 5-6 1-5Z"/>', list:'<path d="M8 5h13M8 12h13M8 19h13M3 5h.01M3 12h.01M3 19h.01"/>', check:'<path d="m5 12 4 4L20 5"/>', lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v3"/>', send:'<path d="m3 3 18 9-18 9 3-9Zm3 9h15"/>', settings:'<path d="m9 3-1 3-3 1 1 4-2 2 2 3 3-1 2 3 4-1 1-3 3-1-1-4 2-2-2-3-3 1-2-3Z"/><circle cx="12" cy="11" r="3"/>', wallet:'<rect x="3" y="5" width="18" height="15" rx="2"/><path d="M3 8h18M17 13h4v4h-4Z"/>', logout:'<path d="M9 4H4v16h5M9 12h12m-5-5 5 5-5 5"/>', photo:'<rect x="3" y="4" width="18" height="16" rx="2"/><circle cx="8" cy="9" r="2"/><path d="m3 17 5-5 4 4 3-3 6 6"/>'
};
const icon = name => `<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name] || icons.space}</svg>`;
function hydrateIcons(root = document) { $$('[data-icon]',root).forEach(el => { el.innerHTML = icon(el.dataset.icon); }); }
const categories = {all:['Все места','list'],parking:['Парковки','parking'],garage:['Гаражи','space'],storage:['Хранение','box'],workshop:['Мастерские','workshop'],room:['Рабочие места','space']};
const singular = {parking:'Парковка',garage:'Гараж',storage:'Кладовая',workshop:'Мастерская',room:'Рабочее место'};
const seed = [
 {id:'g1',title:'Гараж рядом с метро',category:'garage',address:'ул. Дуси Ковальчук, 250',district:'Заельцовский',area:18,hour:150,day:750,month:6500,lat:55.061,lon:82.914,access:'pin',image:'assets/garage.jpg',description:'Отдельный закрытый гараж для автомобиля, сезонных вещей или небольшого оборудования. Сухое помещение, освещение и розетка.',features:'Электричество · сухое помещение · отдельный въезд'},
 {id:'s1',title:'Кладовая для сезонных вещей',category:'storage',address:'ул. Крылова, 36',district:'Центральный',area:6,hour:80,day:280,month:2400,lat:55.041,lon:82.939,access:'pin',image:'assets/storage.jpg',description:'Место для коробок, спортивного инвентаря и вещей на время переезда. Подъезд без ступеней, тележка для разгрузки.',features:'Сухое хранение · тележка · освещение'},
 {id:'p1',title:'Место в подземном паркинге',category:'parking',address:'ул. Военная, 9',district:'Октябрьский',area:15,hour:90,day:550,month:7200,lat:55.023,lon:82.941,access:'qr',image:'assets/parking.jpg',description:'Крытое машиноместо для легкового автомобиля. Удобный въезд с улицы Военной. Высота въезда — 2,1 м.',features:'Крытая парковка · освещение · видеонаблюдение'},
 {id:'w1',title:'Мастерская для вашего проекта',category:'workshop',address:'ул. Фабричная, 17',district:'Железнодорожный',area:24,hour:350,day:1800,month:18000,lat:55.018,lon:82.908,access:'host',image:'assets/workshop.jpg',description:'Рабочее помещение с верстаком для сборки и ремонта. Подойдёт для небольших проектов без шумных и пыльных работ.',features:'Верстак · электричество · вентиляция'},
 {id:'g2',title:'Тёплый гараж на левом берегу',category:'garage',address:'ул. Немировича-Данченко, 122',district:'Кировский',area:21,hour:180,day:850,month:7900,lat:54.987,lon:82.891,access:'pin',image:'assets/garage.jpg',description:'Закрытый гараж с ровным полом и удобным подъездом. Можно разместить автомобиль и несколько стеллажей с вещами.',features:'Освещение · отопление · удобный подъезд'},
 {id:'s2',title:'Небольшой склад для товара',category:'storage',address:'ул. Депутатская, 46',district:'Центральный',area:12,hour:120,day:490,month:4300,lat:55.028,lon:82.926,access:'host',image:'assets/storage.jpg',description:'Помещение для коробок и небольших партий товара. Подходит для продавцов маркетплейсов и интернет-магазинов.',features:'Стеллажи · разгрузка · сухое хранение'},
 {id:'p2',title:'Парковка у площади Ленина',category:'parking',address:'ул. Орджоникидзе, 23',district:'Центральный',area:14,hour:70,day:420,month:5800,lat:55.034,lon:82.923,access:'host',image:'assets/parking.jpg',description:'Открытое парковочное место рядом с центром. Для легкового автомобиля. Удобно для рабочих встреч и прогулок по центру.',features:'В центре · отдельное место · круглосуточно'},
 {id:'r1',title:'Комната для встреч',category:'room',address:'Красный проспект, 50',district:'Центральный',area:10,hour:250,day:1400,month:14000,lat:55.042,lon:82.918,access:'host',image:'assets/room.jpg',description:'Спокойное пространство для разговоров и небольших встреч. Мягкая мебель, журнальный стол и Wi-Fi.',features:'Wi-Fi · мягкая мебель · отдельное помещение'}
].map(item => ({...item,demo:true,published:true,active:true,rules:'Без проживания, хранения горючих и опасных веществ. Соблюдайте чистоту и согласованные часы доступа.'}));
const STORE_KEY = 'spacego.site.v1';
const initial = () => ({version:1,profile:null,favorites:[],bookings:[],spaces:[],threads:[],reviews:[],preferences:{notifications:true,publicName:false}});
let db;
try { db = JSON.parse(localStorage.getItem(STORE_KEY)) || initial(); if (db.version !== 1) db = initial(); } catch { db = initial(); }
const ui = {category:'all',query:'',start:'',end:'',maxPrice:'',minArea:'',sort:'default',map:false,bookingTab:'upcoming',thread:null,ownerStep:1,ownerDraft:null};
const main = $('#main'), modal = $('#modal'), body = $('#modalBody');
const money = n => new Intl.NumberFormat('ru-RU').format(n) + ' ₽';
const dateTime = v => new Date(v).toLocaleString('ru-RU',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'});
const localDate = date => { const d = new Date(date); return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16); };
const uid = () => crypto.randomUUID();
const allSpaces = () => [...seed,...db.spaces];
const space = id => allSpaces().find(x => x.id === id);
const activeStatus = rentalStatus;
const statusLabel = {upcoming:'Предстоящая аренда',active:'Аренда идёт',completed:'Завершена',cancelled:'Отменена',unpaid:'Ожидает тестовой оплаты',expired:'Срок бронирования истёк'};
const overlap = intervalsOverlap;
const available = (id,start,end,ignore) => !db.bookings.some(b => b.id !== ignore && b.spaceId === id && !b.cancelled && new Date(b.end)>new Date() && overlap(start,end,b.start,b.end)) && !(space(id)?.blocks||[]).some(b=>overlap(start,end,b.start,b.end));
function save() { try { localStorage.setItem(STORE_KEY,JSON.stringify(db)); } catch { throw new Error('Не удалось сохранить данные. Попробуйте изображение меньшего размера или освободите место в браузере.'); } updateShell(); }
function toast(text) { const t = $('#toast'); t.textContent=text;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),4000); }
function closeModal() { modal.close(); body.innerHTML=''; }
function showModal(title,html,narrow=false) { $('#modalTitle').textContent=title;modal.classList.toggle('narrow',narrow);body.innerHTML=html;if(!modal.open)modal.showModal();hydrateIcons(body); }
const navItems = [['search','Поиск','search'],['favorites','Избранное','heart'],['bookings','Бронирования','calendar'],['messages','Сообщения','message'],['profile','Профиль','profile']];
const route = () => location.hash.slice(1).split('/')[0] || 'search';
function navigate(to) { if(location.hash === '#'+to) render();else location.hash=to; }
function updateShell() {
 const current = ['owner','settings','payments'].includes(route()) ? 'profile' : route();
 const unread = db.preferences.notifications ? db.threads.filter(t=>t.unread).length : 0;
 $('#desktopNav').innerHTML=navItems.map(([id,label,name])=>`<a class="nav-link ${current===id?'active':''}" href="#${id}" ${current===id?'aria-current="page"':''}>${icon(name)}${label}${id==='messages'&&unread?`<span class="badge-count">${unread}</span>`:''}</a>`).join('');
 $('#bottomNav').innerHTML=navItems.map(([id,label,name])=>`<a href="#${id}" class="${current===id?'active':''}" ${current===id?'aria-current="page"':''}>${icon(name)}<span>${id==='bookings'?'Брони':label}</span>${id==='messages'&&unread?`<span class="badge-count">${unread}</span>`:''}</a>`).join('');
 $('#sidebarName').textContent=db.profile?.name||'Гость';$('#sidebarAvatar').innerHTML=avatar(false);hydrateIcons();
}
function avatar(large=false) { if(db.profile?.avatar)return `<img src="${escape(db.profile.avatar)}" alt="Ваш аватар">`;return escape((db.profile?.name||'Гость').split(/\s+/).slice(0,2).map(p=>p[0]).join('').toUpperCase()); }
function heading(title,subtitle='',action='') { return `<div class="page-head"><div><h1>${title}</h1>${subtitle?`<p>${subtitle}</p>`:''}</div>${action}</div>`; }
function empty(title,text,action='',name='space') { return `<section class="empty"><div class="empty-symbol">${icon(name)}</div><h2>${title}</h2><p>${text}</p>${action}</section>`; }
function countWord(n) { return `${n} ${n%10===1&&n%100!==11?'место':n%10>=2&&n%10<=4&&(n%100<12||n%100>14)?'места':'мест'}`; }
function filtered() { return allSpaces().filter(x=>x.active&&x.published).filter(x=>ui.category==='all'||x.category===ui.category).filter(x=>`${x.title} ${x.address} ${x.district}`.toLowerCase().includes(ui.query.toLowerCase())).filter(x=>!ui.maxPrice||x.day<=+ui.maxPrice).filter(x=>!ui.minArea||x.area>=+ui.minArea).filter(x=>!ui.start||!ui.end||available(x.id,ui.start,ui.end)).sort((a,b)=>ui.sort==='low'?a.day-b.day:ui.sort==='high'?b.day-a.day:ui.sort==='area'?b.area-a.area:0); }
function card(x,owner=false) { const fav=db.favorites.includes(x.id);return `<article class="space-card"><div class="card-media"><a href="#space/${escape(x.id)}" aria-label="${escape(x.title)}"><img src="${escape(x.image||'assets/storage.jpg')}" alt="${escape(x.demo?'Иллюстрация к демонстрационному объявлению: '+singular[x.category]:x.title)}" loading="lazy"></a>${!owner?`<button class="favorite ${fav?'on':''}" data-action="favorite" data-id="${x.id}" aria-label="${fav?'Убрать из':'Добавить в'} избранное" aria-pressed="${fav}">${icon('heart')}</button>`:''}<span class="card-tag">${singular[x.category]} · ${x.area} м²</span></div><div class="card-copy"><h2><a href="#space/${escape(x.id)}">${escape(x.title)}</a></h2><p>${escape(x.address)}</p><div class="card-bottom"><span class="card-price">${money(x.day)} <small>/ день</small></span>${!owner?'<span class="available">Доступно</span>':''}</div>${owner?`<div class="card-status">${!x.published?'Черновик':x.active?'Опубликовано':'Скрыто'}</div><div class="card-owner-actions"><button class="button" data-action="edit-space" data-id="${x.id}">Изменить</button><button class="button" data-action="visibility" data-id="${x.id}">${!x.published?'Опубликовать':x.active?'Скрыть':'Показать'}</button><button class="button" data-action="availability" data-id="${x.id}">Календарь</button><button class="button" data-action="delete-space" data-id="${x.id}">Удалить</button></div>`:''}</div></article>`; }
let mapInstance = null;
function renderCatalog() {
 if(mapInstance){mapInstance.remove();mapInstance=null;}
 const items=filtered(), filterCount=Number(Boolean(ui.maxPrice))+Number(Boolean(ui.minArea));
 main.innerHTML=heading('Найдите своё пространство','Гаражи, парковки и хранение в Новосибирске')+`<form class="search-panel" id="searchForm"><div class="search-field search-input">${icon('search')}<span><label for="query">Район, улица или название</label><input id="query" name="query" value="${escape(ui.query)}" placeholder="Где ищем пространство?" autocomplete="off"></span></div><div class="search-field">${icon('calendar')}<span><label for="start">Начало аренды</label><input type="datetime-local" id="start" name="start" value="${ui.start}" aria-label="Начало аренды"></span></div><div class="search-field"><span><label for="end">Окончание</label><input type="datetime-local" id="end" name="end" value="${ui.end}" aria-label="Окончание аренды"></span></div><button class="button primary" type="submit">${icon('search')}Найти</button></form><div class="catalog-toolbar"><div class="category-tabs" aria-label="Тип пространства">${Object.entries(categories).map(([id,[label,name]])=>`<button class="category-tab ${ui.category===id?'active':''}" data-action="category" data-id="${id}" aria-pressed="${ui.category===id}">${icon(name)}${label}</button>`).join('')}</div><div class="toolbar-actions"><button class="button compact" data-action="filters">${icon('filters')}Фильтры${filterCount?`<span class="filter-count">${filterCount}</span>`:''}</button><button class="button compact map-toggle" data-action="toggle-map">${icon(ui.map?'list':'map')}${ui.map?'Список':'Карта'}</button></div></div><div class="catalog-layout ${ui.map?'map-mode':''}"><section class="results-column" aria-label="Найденные пространства"><div class="results-top"><strong>Найдено ${countWord(items.length)}</strong><label><span class="sr-only">Сортировка</span><select id="sort" class="sort-select"><option value="default" ${ui.sort==='default'?'selected':''}>По умолчанию</option><option value="low" ${ui.sort==='low'?'selected':''}>Сначала дешевле</option><option value="high" ${ui.sort==='high'?'selected':''}>Сначала дороже</option><option value="area" ${ui.sort==='area'?'selected':''}>По площади</option></select></label></div>${items.length?`<div class="listing-grid">${items.map(x=>card(x)).join('')}</div>`:empty('Подходящих мест нет','Попробуйте другой район, даты или условия поиска.','<button class="button" data-action="reset-filters">Сбросить поиск</button>','search')}</section>${mapHTML(items)}</div><p class="catalog-note">В каталоге демонстрационные объявления. Тестовое бронирование сохраняется на этом устройстве. <button data-action="about">Подробнее о прототипе</button></p>`;
 const canvas=$('#mapCanvas');requestAnimationFrame(()=>{if(canvas?.isConnected)mountMap(items);});
}
function mapHTML(items) { const pts=items.map(x=>`${x.lon},${x.lat},pm2gnm`).join('~');return `<aside class="map-panel" aria-label="Карта Новосибирска"><div class="map-frame"><div id="mapCanvas" class="map-canvas" aria-label="Карта пространств Новосибирска"></div><div class="map-overlay"><span>Новосибирск</span><span>${countWord(items.length)} на карте</span></div></div><div class="map-caption"><span>Выберите цену на карте</span><a href="https://yandex.ru/maps/65/novosibirsk/?ll=82.9204%2C55.0302&z=12&pt=${encodeURIComponent(pts)}" target="_blank" rel="noopener">Открыть в Яндексе ↗</a></div></aside>`; }
function mountMap(items){
 const canvas=$('#mapCanvas');if(!canvas||!canvas.offsetWidth||!window.L)return;
 mapInstance=L.map(canvas,{zoomControl:false,scrollWheelZoom:false}).setView([55.0302,82.9204],12);
 L.control.zoom({position:'bottomleft'}).addTo(mapInstance);
 const tiles=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>'}).addTo(mapInstance);
 let failures=0;tiles.on('tileerror',()=>{if(++failures===3)toast('Карта не загрузилась. Можно открыть адрес в Яндексе.');});
 items.forEach(x=>{const marker=L.marker([x.lat,x.lon],{title:`${x.title}, ${money(x.day)} за день`,icon:L.divIcon({className:'price-marker',html:`<span>${money(x.day)}</span>`,iconSize:[76,34],iconAnchor:[38,17]})}).addTo(mapInstance);marker.on('click',()=>navigate(`space/${x.id}`));});
}
function renderFavorites(){const items=db.favorites.map(space).filter(x=>x&&x.published&&x.active);main.innerHTML=heading('Избранное',items.length?`${countWord(items.length)} сохранено для вас`:'Всё, к чему хочется вернуться')+(items.length?`<div class="listing-grid favorites-grid">${items.map(x=>card(x)).join('')}</div>`:empty('Здесь будут ваши места','Нажмите на сердечко в карточке, чтобы сохранить подходящее пространство.','<a class="button primary" href="#search">Найти пространство</a>','heart'));}
function bookingCard(b) {const x=b.snapshot,s=activeStatus(b);return `<article class="booking-card"><img src="${escape(x.image)}" alt="${escape(x.title)}"><div><span class="status ${s==='active'?'active':''}">${statusLabel[s]}</span><h2>${escape(x.title)}</h2><p>${escape(x.address)}</p><p>${dateTime(b.start)} — ${dateTime(b.end)}</p><div class="booking-actions"><button class="button" data-action="booking-detail" data-id="${b.id}">Детали</button>${s==='unpaid'?`<button class="button" data-action="pay" data-id="${b.id}">Тестовая оплата</button>`:''}${['upcoming','unpaid'].includes(s)?`<button class="button" data-action="cancel-booking" data-id="${b.id}">Отменить</button>`:''}<button class="button" data-action="contact" data-id="${b.id}">Сообщения</button>${s==='completed'&&!db.reviews.some(r=>r.bookingId===b.id)?`<button class="button" data-action="review" data-id="${b.id}">Оставить отзыв</button>`:''}</div>${accessUI.card(b)}</div><div class="booking-money">${money(b.total)}<small>${b.paid?'Тестовая оплата':'Без списания денег'}</small></div></article>`;}
function renderBookings(){const tabs=[['upcoming','Предстоящие'],['active','Активные'],['completed','Завершённые'],['cancelled','Отменённые']];const items=db.bookings.filter(b=>ui.bookingTab==='upcoming'?['upcoming','unpaid'].includes(activeStatus(b)):ui.bookingTab==='cancelled'?['cancelled','expired'].includes(activeStatus(b)):activeStatus(b)===ui.bookingTab).sort((a,b)=>new Date(b.start)-new Date(a.start));main.innerHTML=heading('Бронирования','Ваше время, адрес и доступ — в одном месте')+`<div class="tabs">${tabs.map(([id,label])=>`<button class="${ui.bookingTab===id?'active':''}" data-action="booking-tab" data-id="${id}">${label}</button>`).join('')}</div>`+(items.length?`<div class="section-stack">${items.map(bookingCard).join('')}</div>`:empty('Бронирований пока нет','Выберите пространство и удобное время. Созданная бронь появится здесь.','<a class="button primary" href="#search">Перейти к поиску</a>','calendar'));}
function renderProfile(){const p=db.profile;main.innerHTML=heading('Профиль','Ваш кабинет SPACEGO')+`<div class="profile-layout"><section class="panel"><div class="identity"><span class="avatar large">${avatar(true)}</span><div><h2>${escape(p?.name||'Ваш профиль')}</h2><p>${escape(p?.email||'Добавьте имя и контакты')}</p></div></div><div class="profile-stats"><div><strong>${db.bookings.length}</strong><small>бронирований</small></div><div><strong>${db.favorites.length}</strong><small>в избранном</small></div><div><strong>${db.spaces.length}</strong><small>пространств</small></div></div><a class="button primary" href="#settings">${p?'Редактировать профиль':'Создать локальный профиль'}</a><p class="profile-notice">Профиль хранится на этом устройстве. Для входа в помещение отправьте его на подтверждение владельцу из бронирования.</p></section><section class="panel"><h2>Ваш SPACEGO</h2><div class="profile-links"><button data-action="bookings">${icon('calendar')}Бронирования${icon('chevron')}</button><button data-action="owner">${icon('space')}Мои пространства${icon('chevron')}</button><button data-action="payments">${icon('wallet')}Платежи и доход${icon('chevron')}</button><button data-action="settings">${icon('settings')}Настройки${icon('chevron')}</button><button data-action="about">${icon('help')}Как работает прототип${icon('chevron')}</button></div></section></div>`;}
function renderSettings(){const p=db.profile||{};main.innerHTML=heading('Настройки','Имя, контакты и данные на вашем устройстве','<a class="button compact" href="#profile">Назад в профиль</a>')+`<div class="settings-layout"><section class="settings-section"><div><h2>Личные данные</h2><p>Так вы будете представлены в своём кабинете.</p></div><form id="profileForm" class="panel form-stack"><div class="field"><label for="name">Имя и фамилия</label><input id="name" name="name" value="${escape(p.name||'')}" maxlength="70" autocomplete="name" required></div><div class="field"><label for="email">Электронная почта</label><input id="email" name="email" value="${escape(p.email||'')}" type="email" autocomplete="email" required></div><div class="field"><label for="phone">Телефон</label><input id="phone" name="phone" value="${escape(p.phone||'')}" type="tel" autocomplete="tel" maxlength="30"></div><div class="field"><label for="avatarFile">Фото профиля</label><input id="avatarFile" name="avatar" type="file" accept="image/png,image/jpeg,image/webp"><small>PNG, JPEG или WebP до 400 КБ</small></div><p class="form-message" role="alert"></p><button class="button primary" type="submit">Сохранить профиль</button></form></section><section class="settings-section"><div><h2>Предпочтения</h2><p>Приватность и уведомления внутри прототипа.</p></div><form id="preferencesForm" class="panel form-stack"><label class="checkbox-row"><input type="checkbox" name="notifications" ${db.preferences.notifications?'checked':''}>Показывать индикатор новых сообщений</label><label class="checkbox-row"><input type="checkbox" name="publicName" ${db.preferences.publicName?'checked':''}>Показывать моё имя в моих объявлениях</label><button class="button" type="submit">Сохранить настройки</button></form></section><section class="settings-section"><div><h2>Данные устройства</h2><p>Удаление очистит профиль, избранное, брони, объявления и переписку этого прототипа.</p></div><div class="panel"><button class="danger-link" data-action="delete-profile">Удалить локальные данные</button></div></section></div>`;}
function renderOwner(){const items=db.spaces;const income=db.bookings.filter(b=>b.paid&&!b.cancelled&&db.spaces.some(x=>x.id===b.spaceId)).reduce((s,b)=>s+b.rent,0);main.innerHTML=heading('Мои пространства',`${items.filter(x=>x.published&&x.active).length} опубликовано · ${money(income)} тестовых начислений`,'<button class="button primary" data-action="new-space">'+icon('plus')+'Добавить место</button>')+accessUI.ownerPanel()+(items.length?`<div class="listing-grid favorites-grid">${items.map(x=>card(x,true)).join('')}</div>`:empty('Дайте пространству новую работу','Добавьте гараж, парковочное место или кладовую. Вы задаёте цену и доступность.','<button class="button primary" data-action="new-space">Добавить пространство</button>'));}
function renderPayments(){const items=db.bookings.filter(b=>b.paid);const total=items.reduce((s,b)=>s+b.total,0);main.innerHTML=heading('Платежи и доход',`Всего тестовых операций: ${items.length} · ${money(total)}`,'<a class="button compact" href="#profile">В профиль</a>')+(items.length?`<div class="table-wrap"><table><thead><tr><th>Пространство</th><th>Дата</th><th class="num">Аренда</th><th class="num">Сервисный сбор</th><th class="num">Итого</th><th>Статус</th></tr></thead><tbody>${items.map(b=>`<tr><td>${escape(b.snapshot.title)}</td><td>${dateTime(b.paidAt)}</td><td class="num">${money(b.rent)}</td><td class="num">${money(b.fee)}</td><td class="num">${money(b.total)}</td><td>${b.cancelled?'Тестовый возврат':'Демо · оплачено'}</td></tr>`).join('')}</tbody></table></div><p class="mini-note">Это история симуляций. Деньги не списываются, выплаты не производятся.</p>`:empty('Операций пока нет','После тестовой оплаты бронирования здесь появится квитанция с расчётом.','','wallet'));}
function renderMessages(){const t=db.threads.find(x=>x.id===ui.thread);if(t)t.unread=false;main.innerHTML=heading('Сообщения','Обсуждайте детали, сохраняйте договорённости')+`<div class="inbox ${t?'has-thread':''}"><aside class="thread-list"><header><h2>Ваши диалоги</h2><button class="button compact" data-action="support">Поддержка</button></header>${db.threads.map(thread=>`<button class="thread-row ${thread.id===t?.id?'selected':''}" data-action="thread" data-id="${thread.id}"><span class="avatar">${escape(thread.title[0])}</span><span><b>${escape(thread.title)}</b><small>${escape(thread.messages.at(-1)?.text||'Новый диалог')}</small></span>${thread.unread?'<span class="badge-count">1</span>':''}</button>`).join('')||'<p class="thread-note">Диалог появится, когда вы откроете сообщения в бронировании или обратитесь в поддержку.</p>'}<p class="thread-note">Демо-переписка. Сообщения сохраняются на этом устройстве и не отправляются реальному владельцу.</p></aside><section class="conversation">${t?`<header><button class="icon-button messages-back" data-action="threads" aria-label="Назад к диалогам">${icon('back')}</button><div><h2>${escape(t.title)}</h2><p>Локальный демонстрационный диалог</p></div>${t.bookingId?`<button class="icon-button" data-action="booking-detail" data-id="${t.bookingId}" aria-label="Открыть бронирование">${icon('space')}</button>`:''}</header><div class="message-history" id="history">${t.messages.map(m=>`<article class="bubble ${m.mine?'mine':''}"><p>${escape(m.text)}</p><small>${m.mine?'Вы':'SPACEGO'} · ${dateTime(m.time)}</small></article>`).join('')||'<p class="muted">Напишите первое сообщение.</p>'}</div><form id="messageForm" class="compose"><label class="sr-only" for="messageText">Ваше сообщение</label><textarea id="messageText" name="text" rows="2" maxlength="3000" placeholder="Написать сообщение…" required></textarea><button class="button primary" type="submit" aria-label="Сохранить сообщение">${icon('send')}</button></form>`:'<p class="conversation-empty">Выберите диалог или создайте обращение в поддержку.</p>'}</section></div>`;if(t){save();requestAnimationFrame(()=>{$('#history').scrollTop=$('#history').scrollHeight;});}}
function render(){closeModal();updateShell();const r=route();const views={search:renderCatalog,favorites:renderFavorites,bookings:renderBookings,messages:renderMessages,profile:renderProfile,settings:renderSettings,owner:renderOwner,payments:renderPayments};if(r==='space'){renderCatalog();openSpace(location.hash.split('/')[1]);}else if(r==='entry'){renderBookings();const [,id,token]=location.hash.slice(1).split('/');accessUI.read(id,token);}else (views[r]||renderCatalog)();if(!navigator.onLine)main.insertAdjacentHTML('afterbegin','<p class="offline-bar">Нет подключения. Локальные данные доступны; карта загрузится после восстановления сети.</p>');hydrateIcons(main);}
function filtersModal(){showModal('Фильтры',`<form id="filterForm" class="dialog-content form-stack"><div class="form-grid"><div class="field"><label for="maxPrice">Цена за день, до ₽</label><input id="maxPrice" name="maxPrice" type="number" min="0" value="${ui.maxPrice}" placeholder="Без ограничения"></div><div class="field"><label for="minArea">Площадь от, м²</label><input id="minArea" name="minArea" type="number" min="0" value="${ui.minArea}" placeholder="Любая"></div></div><div class="dialog-actions"><button class="button" type="button" data-action="reset-filters">Сбросить</button><button class="button primary" type="submit">Показать места</button></div></form>`,true);}
let currentSpace=null;
function openSpace(id){const x=space(id);if(!x){toast('Пространство больше недоступно');return;}currentSpace=x;const start=ui.start||localDate(Date.now()+3600000),end=ui.end||localDate(Date.now()+10800000);const reviews=db.reviews.filter(r=>r.spaceId===id);showModal(x.title,`<a href="${escape(x.image)}" target="_blank" rel="noopener" aria-label="Открыть фото"><img class="detail-photo" src="${escape(x.image)}" alt="${escape(x.demo?'Иллюстрация демонстрационного '+singular[x.category].toLowerCase():x.title)}"></a><div class="detail-layout"><div class="detail-copy"><h3>${escape(x.title)}</h3><div class="detail-meta">${escape(x.address)} · ${escape(x.district)} район</div><div class="detail-facts"><span><strong>${x.area} м²</strong><small>площадь</small></span><span><strong>${x.access==='pin'?'PIN':x.access==='qr'?'QR':'Владелец'}</strong><small>способ доступа</small></span><span><strong>${reviews.length? (reviews.reduce((s,r)=>s+r.rating,0)/reviews.length).toFixed(1):'—'}</strong><small>${reviews.length?'демо-оценка':'нет отзывов'}</small></span></div><p>${escape(x.description)}</p><div class="detail-rule"><h4>Что есть в пространстве</h4><p>${escape(x.features||'Уточните условия перед арендой')}</p></div><div class="detail-rule"><h4>Правила использования</h4><p>${escape(x.rules)}</p></div><div class="detail-rule"><h4>${x.demo?'Демонстрационное объявление':db.preferences.publicName?escape(db.profile?.name||'Владелец'):'Частный владелец'}</h4><p>${x.demo?'Фото иллюстрирует тип помещения. Объявление, адрес и цена используются для проверки сценариев.':'Объявление сохранено на этом устройстве.'}</p></div>${reviews.length?`<div class="detail-rule"><h4>Демо-отзывы</h4>${reviews.map(r=>`<p>${r.rating}/5 · ${escape(r.text)}</p>`).join('')}</div>`:''}<a class="text-button" href="https://yandex.ru/maps/?pt=${x.lon},${x.lat}&z=16&l=map" target="_blank" rel="noopener">${icon('pin')}Посмотреть адрес на карте</a></div><form id="bookingForm" class="booking-form"><div class="price-heading"><strong>${money(x.day)}</strong><span>/ день</span></div><div class="form-stack"><div class="field"><label for="rate">Тариф</label><select id="rate" name="rate">${x.hour?'<option value="hour">Почасово</option>':''}<option value="day" selected>Посуточно</option>${x.month?'<option value="month">На 30 дней</option>':''}</select></div><div class="field"><label for="bookingStart">Начало аренды</label><input type="datetime-local" id="bookingStart" name="start" value="${start}" required></div><div class="field"><label for="bookingEnd">Окончание аренды</label><input type="datetime-local" id="bookingEnd" name="end" value="${end}" required></div></div><div class="quote" id="quote"></div><p class="form-message" id="bookingError" role="alert"></p><button class="button primary full" type="submit" ${!x.active||!x.published?'disabled':''}>Забронировать</button><p class="mini-note">Тестовая бронь. Деньги не списываются, доступ к физическому объекту не предоставляется.</p></form></div>`);updateQuote();}
function quoteData(form){return rentalQuote(currentSpace,form.elements.rate.value,form.elements.start.value,form.elements.end.value);}
function updateQuote(){const f=$('#bookingForm');if(!f)return;try{const q=quoteData(f);$('#quote').innerHTML=`<div><span>${q.units} ${q.rate==='hour'?'ч.':q.rate==='day'?'дн.':'× 30 дней'} × ${money(currentSpace[q.rate])}</span><span class="number">${money(q.rent)}</span></div><div><span>Сервисный сбор · 15%</span><span class="number">${money(q.fee)}</span></div><div class="total"><span>Итого</span><span class="number">${money(q.total)}</span></div>`;$('#bookingError').textContent='';}catch(e){$('#quote').innerHTML='';$('#bookingError').textContent=e.message;}}
function paymentModal(id){const b=db.bookings.find(x=>x.id===id);if(!b||b.cancelled)return;showModal('Подтверждение бронирования',`<div class="dialog-content"><div class="book-summary"><h3>${escape(b.snapshot.title)}</h3><p>${escape(b.snapshot.address)}</p><p>${dateTime(b.start)} — ${dateTime(b.end)}</p><strong>${money(b.total)}</strong><p>Включая сервисный сбор ${money(b.fee)}</p></div><p class="test-note">Это тестовая оплата. Не вводите данные карты: реальные списания и бронирование у владельца не производятся.</p><div class="dialog-actions"><button class="button" data-action="close">Позже</button><button class="button primary" data-action="confirm-pay" data-id="${id}">Оплатить в тестовом режиме</button></div></div>`,true);}
function bookingDetails(id){const b=db.bookings.find(x=>x.id===id);if(!b)return;const s=activeStatus(b);showModal('Ваше бронирование',`<div class="dialog-content"><div class="book-summary"><span class="status ${s==='active'?'active':''}">${statusLabel[s]}</span><h3>${escape(b.snapshot.title)}</h3><p>${escape(b.snapshot.address)}</p><p>${dateTime(b.start)} — ${dateTime(b.end)}</p><strong>${money(b.total)}</strong></div>${accessUI.card(b)}<p class="test-note">Тестовая аренда. QR выдаётся после подтверждения профиля владельцем.</p><div class="dialog-actions">${s==='unpaid'?`<button class="button primary" data-action="pay" data-id="${id}">Перейти к оплате</button>`:s==='active'?`<button class="button primary" data-action="access" data-id="${id}">Получить тестовый доступ</button>`:''}<button class="button" data-action="contact" data-id="${id}">Открыть сообщения</button></div></div>`,true);}
function accessModal(id){accessUI.open(id);}
function confirmModal(title,text,action,id,label='Подтвердить'){showModal(title,`<div class="dialog-content"><p>${escape(text)}</p><div class="dialog-actions"><button class="button" data-action="close">Назад</button><button class="button danger" data-action="${action}" data-id="${escape(id||'')}">${label}</button></div></div>`,true);}
function startThread(bookingId){let t=db.threads.find(x=>bookingId?x.bookingId===bookingId:!x.bookingId);if(!t){const b=db.bookings.find(x=>x.id===bookingId);t={id:uid(),bookingId:bookingId||null,title:b?b.snapshot.title:'Поддержка SPACEGO',messages:[{mine:false,text:b?'Это демо-диалог по вашему бронированию. Здесь можно сохранить вопросы и детали аренды. Реальному владельцу сообщения не отправляются.':'Это демонстрационная поддержка. Вы можете сохранить обращение; реальная команда его не получит.',time:new Date().toISOString()}]};db.threads.push(t);}ui.thread=t.id;save();closeModal();navigate('messages');}
let ownerPhoto='';
function ownerModal(id){const x=db.spaces.find(x=>x.id===id);ui.ownerStep=1;ui.ownerDraft=x?{...x}:{title:'',category:'garage',district:'Центральный',address:'',area:'',hour:0,day:'',month:0,access:'host',description:'',features:'',rules:'Без проживания и хранения опасных веществ.',lat:55.0302,lon:82.9204};ownerPhoto=x?.image||'';ownerWizard();}
function field(label,name,type='text',attrs=''){return `<div class="field"><label for="owner-${name}">${label}</label><input id="owner-${name}" name="${name}" type="${type}" value="${escape(ui.ownerDraft[name])}" ${attrs}></div>`;}
function ownerWizard(){const d=ui.ownerDraft,s=ui.ownerStep;showModal(d.id?'Изменить пространство':'Добавить пространство',`<form id="ownerForm" class="dialog-content"><div class="step-track">${[1,2,3].map(n=>`<span class="${n<=s?'current':''}"></span>`).join('')}</div><div class="step-heading"><small>Шаг ${s} из 3</small><h3>${s===1?'Что и где вы сдаёте':s===2?'Условия и фотографии':'Цена и доступ'}</h3></div><div class="form-stack">${s===1?`${field('Название','title','text','maxlength="80" required')}<div class="field"><label for="owner-category">Тип пространства</label><select id="owner-category" name="category">${Object.entries(singular).map(([id,label])=>`<option value="${id}" ${d.category===id?'selected':''}>${label}</option>`).join('')}</select></div><div class="form-grid">${field('Район','district','text','required')}${field('Площадь, м²','area','number','min="1" max="10000" required')}</div>${field('Адрес в Новосибирске','address','text','required')}<div class="form-grid">${field('Широта','lat','number','step="any" min="54" max="56" required')}${field('Долгота','lon','number','step="any" min="82" max="84" required')}</div><p class="mini-note">Укажите координаты вашего места, чтобы оно появилось на карте.</p>`:s===2?`<div class="field"><label for="description">Описание</label><textarea id="description" name="description" rows="4" maxlength="1500" required>${escape(d.description)}</textarea></div>${field('Оснащение','features','text','maxlength="200"')}<div class="field"><label for="rules">Правила использования</label><textarea id="rules" name="rules" rows="3" maxlength="1000">${escape(d.rules)}</textarea></div><div class="field"><label for="ownerPhoto">Фотография</label><input id="ownerPhoto" type="file" accept="image/jpeg,image/png,image/webp"><small>До 1 МБ. Сохранится на этом устройстве.</small><div class="photo-preview" id="photoPreview">${ownerPhoto?`<img src="${escape(ownerPhoto)}" alt="Фото пространства">`:''}</div></div>`:`<div class="form-grid">${field('За час, ₽ (0 — отключён)','hour','number','min="0" max="1000000" required')}${field('За день, ₽','day','number','min="1" max="1000000" required')}</div>${field('За 30 дней, ₽ (0 — отключён)','month','number','min="0" max="10000000" required')}<div class="field"><label for="access">Способ доступа</label><select id="access" name="access"><option value="host" ${d.access==='host'?'selected':''}>Встреча с владельцем</option><option value="pin" ${d.access==='pin'?'selected':''}>PIN-код · тестовый</option><option value="qr" ${d.access==='qr'?'selected':''}>QR-доступ · тестовый</option></select></div><p class="test-note">Объявление появится в прототипе на этом устройстве. Реальные замки и выплаты не подключены.</p>`}<p class="form-message" role="alert"></p></div><div class="dialog-actions">${s>1?'<button class="button" type="button" data-action="owner-back">Назад</button>':''}${s===3?'<button class="button" type="button" data-action="save-draft">В черновик</button>':''}<button class="button primary" type="submit">${s===3?(d.id?'Сохранить и опубликовать':'Опубликовать'):'Продолжить'}</button></div></form>`);}
function ownerCollect(){const form=$('#ownerForm');if(!form.reportValidity())return false;for(const [key,value] of new FormData(form))ui.ownerDraft[key]=['area','hour','day','month','lat','lon'].includes(key)?Number(value):value;return true;}
function persistSpace(published){if(!ownerCollect())return;const d=ui.ownerDraft;if(!d.title||!d.description||!d.address||!d.day)throw new Error('Заполните название, адрес, описание и цену за день.');const x={...d,id:d.id||uid(),image:ownerPhoto||'assets/storage.jpg',demo:false,published,active:published,blocks:d.blocks||[]};const index=db.spaces.findIndex(v=>v.id===x.id);if(index>=0)db.spaces[index]=x;else db.spaces.push(x);save();closeModal();navigate('owner');toast(published?'Объявление опубликовано на этом устройстве':'Черновик сохранён');}
function availabilityModal(id){const x=db.spaces.find(x=>x.id===id);if(!x)return;showModal('Календарь пространства',`<div class="dialog-content"><h3>${escape(x.title)}</h3><p class="mini-note">Закройте время, когда пространство нельзя бронировать.</p><form id="blockForm" data-id="${id}" class="form-stack" style="margin-top:20px"><div class="form-grid"><div class="field"><label for="blockStart">С</label><input type="datetime-local" id="blockStart" name="start" required></div><div class="field"><label for="blockEnd">По</label><input type="datetime-local" id="blockEnd" name="end" required></div></div><p class="form-message" role="alert"></p><button class="button" type="submit">Закрыть время</button></form><div class="section-stack" style="margin-top:24px">${(x.blocks||[]).map((b,i)=>`<div class="owner-booking"><p>${dateTime(b.start)} — ${dateTime(b.end)}</p><button class="text-button" data-action="remove-block" data-id="${id}" data-index="${i}">Открыть время</button></div>`).join('')||'<p class="muted">Закрытых интервалов нет.</p>'}</div></div>`,true);}
function about(){showModal('О прототипе SPACEGO',`<div class="dialog-content about-copy"><p>SPACEGO — аренда свободных пространств по принципу каршеринга: место на карте, удобное время, бронирование и доступ.</p><h3>Что работает</h3><p>Поиск, фильтры, карта, избранное, бронирования с проверкой пересечений, расчёт стоимости и сбора 15%, объявления, календарь, профиль и локальные сообщения.</p><h3>Где хранятся данные</h3><p>В браузере на вашем устройстве. После обновления страницы данные сохраняются. Это не многопользовательский сервис: между устройствами синхронизации нет.</p><h3>Оплата и доступ</h3><p>Платёж моделируется без карты и списания денег. После тестовой оплаты арендатор отправляет профиль владельцу. В демо-кабинете владельца можно подтвердить или отклонить заявку, выдать QR и отозвать доступ. QR действует только в оплаченный срок аренды и не открывает физический замок.</p><h3>Изображения</h3><p>Фотографии иллюстрируют типы помещений и не являются фотографиями реальных предложений в Новосибирске. <a href="credits.html" target="_blank" rel="noopener">Источники и лицензии</a>.</p><h3>Основа проекта</h3><p><a href="https://chatgpt.com/share/6adef704-f188-83ed-b00b-a3ce3d0fe87b" target="_blank" rel="noopener">Опубликованный чат о SPACEGO</a></p></div>`,true);}
const accessUI=createAccessUI({db:()=>db,save,showModal,toast,navigate,refresh:()=>{if(route()==='owner')renderOwner();else renderBookings();}});
async function handleAction(action,id,target){
 if(accessUI.handle(action,id))return;
 switch(action){
  case 'search':case 'favorites':case 'bookings':case 'messages':case 'profile':case 'owner':case 'settings':case 'payments':navigate(action);break;
  case 'close':closeModal();break;
  case 'about':about();break;
  case 'favorite': {const i=db.favorites.indexOf(id);if(i>=0)db.favorites.splice(i,1);else db.favorites.push(id);save();if(route()==='favorites')renderFavorites();else{target.classList.toggle('on',i<0);target.setAttribute('aria-pressed',i<0);target.setAttribute('aria-label',i<0?'Убрать из избранного':'Добавить в избранное');}toast(i<0?'Сохранено в избранное':'Убрано из избранного');break;}
  case 'category':ui.category=id;renderCatalog();break;
  case 'filters':filtersModal();break;
  case 'toggle-map':ui.map=!ui.map;renderCatalog();break;
  case 'reset-filters':Object.assign(ui,{query:'',category:'all',start:'',end:'',maxPrice:'',minArea:''});closeModal();renderCatalog();break;
  case 'booking-tab':ui.bookingTab=id;renderBookings();break;
  case 'booking-detail':bookingDetails(id);break;
  case 'pay':paymentModal(id);break;
  case 'confirm-pay':{const b=db.bookings.find(x=>x.id===id);if(!b||b.cancelled||b.paid)break;if(new Date(b.end)<=new Date())throw new Error('Время бронирования уже истекло. Выберите новый интервал.');if(!available(b.spaceId,b.start,b.end,b.id))throw new Error('Это время уже занято. Выберите другой интервал.');b.paid=true;b.paidAt=new Date().toISOString();save();closeModal();ui.bookingTab=activeStatus(b)==='active'?'active':'upcoming';navigate('bookings');toast('Тестовая оплата подтверждена. Деньги не списаны.');break;}
  case 'cancel-booking':confirmModal('Отменить бронирование?','Время снова станет доступно для аренды. Реальных списаний и возвратов нет.','confirm-cancel',id,'Отменить бронь');break;
  case 'confirm-cancel':{const b=db.bookings.find(x=>x.id===id);if(!b||!['upcoming','unpaid'].includes(activeStatus(b)))throw new Error('Эту аренду уже нельзя отменить.');b.cancelled=true;save();closeModal();renderBookings();toast('Бронирование отменено');break;}
  case 'access':accessModal(id);break;
  case 'verify-code':{const b=db.bookings.find(x=>x.id===id);accessUI.read(id,b?.accessRequest?.token);break;}
  case 'contact':startThread(id);break;
  case 'support':startThread(null);break;
  case 'thread':ui.thread=id;renderMessages();break;
  case 'threads':ui.thread=null;renderMessages();break;
  case 'review':showModal('Отзыв о пространстве',`<form id="reviewForm" data-id="${id}" class="dialog-content form-stack"><div class="field"><label for="rating">Ваша оценка</label><select id="rating" name="rating" required><option value="">Выберите</option>${[5,4,3,2,1].map(n=>`<option>${n}</option>`).join('')}</select></div><div class="field"><label for="reviewText">Впечатления от аренды</label><textarea id="reviewText" name="text" rows="4" maxlength="1000" required></textarea></div><p class="mini-note">Отзыв сохраняется как демонстрационный на этом устройстве.</p><button class="button primary" type="submit">Сохранить отзыв</button></form>`,true);break;
  case 'new-space':ownerModal();break;
  case 'edit-space':ownerModal(id);break;
  case 'owner-back':ownerCollect();ui.ownerStep--;ownerWizard();break;
  case 'save-draft':persistSpace(false);break;
  case 'visibility':{const x=db.spaces.find(x=>x.id===id);if(!x)break;if(!x.published){x.published=true;x.active=true;}else x.active=!x.active;save();renderOwner();toast(x.active?'Объявление опубликовано':'Объявление скрыто');break;}
  case 'delete-space':confirmModal('Удалить объявление?','Объявление исчезнет из каталога на этом устройстве. История бронирований сохранится.','confirm-delete-space',id,'Удалить');break;
  case 'confirm-delete-space':if(db.bookings.some(b=>b.spaceId===id&&['upcoming','active','unpaid'].includes(activeStatus(b))))throw new Error('Сначала отмените предстоящие брони или дождитесь завершения активной аренды.');db.spaces=db.spaces.filter(x=>x.id!==id);db.favorites=db.favorites.filter(x=>x!==id);save();closeModal();renderOwner();toast('Объявление удалено');break;
  case 'availability':availabilityModal(id);break;
  case 'remove-block':{const x=db.spaces.find(x=>x.id===id);x.blocks.splice(Number(target.dataset.index),1);save();availabilityModal(id);toast('Время открыто для аренды');break;}
  case 'delete-profile':confirmModal('Удалить локальные данные?','Профиль, брони, избранное, сообщения и ваши объявления будут удалены из браузера. Отменить действие нельзя.','confirm-delete-profile',null,'Удалить данные');break;
  case 'confirm-delete-profile':db=initial();save();closeModal();navigate('profile');toast('Локальные данные удалены');break;
 }
 hydrateIcons();
}
document.addEventListener('click',event=>{const b=event.target.closest('[data-action]');if(!b)return;event.preventDefault();Promise.resolve(handleAction(b.dataset.action,b.dataset.id,b)).catch(e=>toast(e.message));});
$('#closeModal').addEventListener('click',closeModal);
modal.addEventListener('click',event=>{if(event.target===modal)closeModal();});
document.addEventListener('input',event=>{if(event.target.closest('#bookingForm'))updateQuote();});
document.addEventListener('change',async event=>{if(event.target.id==='sort'){ui.sort=event.target.value;renderCatalog();}if(event.target.id==='ownerPhoto'){try{const f=event.target.files?.[0];if(!f)return;ownerPhoto=await readImage(f,1024*1024);$('#photoPreview').innerHTML=`<img src="${ownerPhoto}" alt="Фото пространства">`;}catch(e){event.target.value='';toast(e.message);}}});
function readImage(file,max){return new Promise((resolve,reject)=>{if(!['image/png','image/jpeg','image/webp'].includes(file.type))return reject(new Error('Выберите PNG, JPEG или WebP.'));if(file.size>max)return reject(new Error(`Изображение слишком большое. Максимум ${Math.round(max/1024)} КБ.`));const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('Не удалось прочитать изображение.'));reader.readAsDataURL(file);});}
document.addEventListener('submit',async event=>{const f=event.target;event.preventDefault();const button=$('[type="submit"]',f);if(button)button.disabled=true;try{
 const data=Object.fromEntries(new FormData(f));
 switch(f.id){
  case 'searchForm':if(Boolean(data.start)!==Boolean(data.end))throw new Error('Укажите обе даты или оставьте их пустыми.');if(data.start&&new Date(data.end)<=new Date(data.start))throw new Error('Окончание должно быть позже начала аренды.');Object.assign(ui,{query:data.query.trim(),start:data.start,end:data.end});renderCatalog();break;
  case 'filterForm':Object.assign(ui,{maxPrice:data.maxPrice,minArea:data.minArea});closeModal();renderCatalog();break;
  case 'bookingForm':{const q=quoteData(f);if(new Date(q.start)<Date.now()-60000)throw new Error('Начало аренды не может быть в прошлом.');if(q.units>365&&q.rate!=='hour')throw new Error('Для теста выберите более короткий период.');if(!available(currentSpace.id,q.start,q.end))throw new Error('Это время уже занято. Выберите другой интервал.');const b={...q,id:uid(),spaceId:currentSpace.id,snapshot:{...currentSpace},paid:false,cancelled:false,pin:String(Math.floor(100000+Math.random()*900000)),createdAt:new Date().toISOString()};db.bookings.push(b);save();paymentModal(b.id);break;}
  case 'profileForm':{const image=f.elements.avatar.files[0]?await readImage(f.elements.avatar.files[0],400*1024):db.profile?.avatar;const profile={name:data.name.trim(),email:data.email.trim(),phone:data.phone.trim(),avatar:image||null,revision:uid()};if(profile.name.length<2)throw new Error('Введите имя хотя бы из двух букв.');db.profile=profile;save();toast('Профиль сохранён на этом устройстве');break;}
  case 'preferencesForm':db.preferences={notifications:f.elements.notifications.checked,publicName:f.elements.publicName.checked};save();toast('Настройки сохранены');break;
  case 'messageForm':{const t=db.threads.find(x=>x.id===ui.thread);const text=data.text.trim();if(!text)throw new Error('Введите сообщение.');t.messages.push({mine:true,text,time:new Date().toISOString()});save();renderMessages();break;}
  case 'ownerForm':if(ui.ownerStep<3){if(ownerCollect()){ui.ownerStep++;ownerWizard();}}else persistSpace(true);break;
  case 'blockForm':{const x=db.spaces.find(x=>x.id===f.dataset.id);if(new Date(data.end)<=new Date(data.start))throw new Error('Окончание должно быть позже начала.');if(new Date(data.end)<=new Date())throw new Error('Выберите будущее время.');if(!available(x.id,data.start,data.end))throw new Error('Этот интервал уже занят или закрыт.');x.blocks=[...(x.blocks||[]),{start:data.start,end:data.end}];save();availabilityModal(x.id);toast('Интервал закрыт для аренды');break;}
  case 'reviewForm':{const b=db.bookings.find(x=>x.id===f.dataset.id);if(!b||activeStatus(b)!=='completed'||db.reviews.some(r=>r.bookingId===b.id))throw new Error('Отзыв доступен после завершения аренды и только один раз.');db.reviews.push({bookingId:b.id,spaceId:b.spaceId,rating:Number(data.rating),text:data.text.trim()});save();closeModal();renderBookings();toast('Демо-отзыв сохранён');break;}
 }
}catch(e){const error=$('.form-message',f);if(error)error.textContent=e.message;else toast(e.message);}finally{if(button?.isConnected)button.disabled=false;}});
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'});});
window.addEventListener('storage',event=>{if(event.key===STORE_KEY){try{db=JSON.parse(event.newValue)||initial();render();}catch{toast('Не удалось прочитать обновлённые данные.');}}});
window.addEventListener('online',()=>toast('Подключение восстановлено'));
window.addEventListener('offline',()=>toast('Нет сети. Данные по-прежнему сохраняются на устройстве.'));
setInterval(()=>{if(route()==='bookings'&&!modal.open)renderBookings();},60000);
hydrateIcons();render();
